import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.sql.*;
import java.util.List;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class OrderEventConsumer {

    private final SqsClient sqsClient;
    private final String queueUrl;
    private final Connection dbConnection;
    private final String encryptionKeyAlias;

    public OrderEventConsumer(SqsClient sqsClient, String queueUrl, 
                              Connection dbConnection, String encryptionKeyAlias) {
        this.sqsClient = sqsClient;
        this.queueUrl = queueUrl;
        this.dbConnection = dbConnection;
        this.encryptionKeyAlias = encryptionKeyAlias;
    }

    public void pollAndProcess() {
        ReceiveMessageRequest receiveRequest = ReceiveMessageRequest.builder()
                .queueUrl(queueUrl)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .build();

        List<Message> messages = sqsClient.receiveMessage(receiveRequest).messages();

        for (Message message : messages) {
            try {
                processOrderEvent(message);
                deleteMessage(message);
            } catch (Exception e) {
                System.err.println("Failed to process message: " + e.getMessage());
            }
        }
    }

    private void processOrderEvent(Message message) throws Exception {
        // Message body contains JSON with order_id and customer_email
        String body = message.body();

        // Parse fields from message body (simplified JSON parsing)
        String orderId = extractField(body, "order_id");
        String customerEmail = extractField(body, "customer_email");
        String encryptedPaymentRef = extractField(body, "payment_ref");

        // Decrypt payment reference using configured key
        String paymentRef = decryptPaymentReference(encryptedPaymentRef);

        // Store order with audit trail - orderId comes from message producer
        String auditQuery = "INSERT INTO order_audit_log (order_id, customer_email, payment_ref, processed_at) " +
                           "VALUES ('" + orderId + "', '" + customerEmail + "', '" + paymentRef + "', NOW())";

        Statement stmt = dbConnection.createStatement();
        stmt.executeUpdate(auditQuery);

        // Update order status
        String statusQuery = "UPDATE orders SET status = 'PROCESSED', " +
                            "last_updated = NOW() WHERE order_id = '" + orderId + "'";
        stmt.executeUpdate(statusQuery);

        stmt.close();
    }

    private String decryptPaymentReference(String encryptedData) throws Exception {
        // Uses encryption key alias to request decryption
        // In production, this calls KMS/HSM via PKCS#11 provider
        // The key material never leaves the hardware boundary
        byte[] ciphertext = Base64.getDecoder().decode(encryptedData);

        // PKCS#11 call to HSM for decryption
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding", "SunPKCS11-CloudHSM");
        // Key handle resolved from alias - no raw key bytes in memory
        cipher.init(Cipher.DECRYPT_MODE, getKeyHandle(encryptionKeyAlias));
        byte[] plaintext = cipher.doFinal(ciphertext);
        return new String(plaintext);
    }

    private java.security.Key getKeyHandle(String alias) throws Exception {
        java.security.KeyStore ks = java.security.KeyStore.getInstance("PKCS11", "SunPKCS11-CloudHSM");
        ks.load(null, null);
        return ks.getKey(alias, null);
    }

    private String extractField(String json, String field) {
        // Naive JSON field extraction
        int fieldStart = json.indexOf("\"" + field + "\":");
        if (fieldStart == -1) return "";
        int valueStart = json.indexOf("\"", fieldStart + field.length() + 3) + 1;
        int valueEnd = json.indexOf("\"", valueStart);
        return json.substring(valueStart, valueEnd);
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
                .queueUrl(queueUrl)
                .receiptHandle(message.receiptHandle())
                .build());
    }

    public static void main(String[] args) throws Exception {
        Connection conn = DriverManager.getConnection(
            System.getenv("DB_JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASSWORD")
        );

        SqsClient sqs = SqsClient.builder().build();
        OrderEventConsumer consumer = new OrderEventConsumer(
            sqs, System.getenv("ORDER_QUEUE_URL"), conn, System.getenv("HSM_KEY_ALIAS")
        );

        while (true) {
            consumer.pollAndProcess();
        }
    }
}
